(()=>{
  const API=()=>window.UNTOZ_COMMAND_API_BASE||'https://untoz-command-api.lovable.app';
  let config=null;
  const esc=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
  async function loadConfig(){try{const r=await fetch(API()+'/api/public/config',{cache:'no-store'});if(!r.ok)return;config=await r.json();install()}catch{}}
  function install(){const card=document.querySelector('#command-auth-gate .command-auth-card');if(!card||!config?.bootstrap_required)return;if(card.querySelector('[data-bootstrap-owner]'))return;const box=document.createElement('details');box.className='command-bootstrap';box.dataset.bootstrapOwner='1';box.innerHTML=`<summary>First Owner Setup →</summary><p>No Untoz staff role exists yet. Create the first Owner account securely.</p><div class="command-bootstrap-grid"><label>Email<input data-bootstrap-email type="email" autocomplete="username"></label><label>Password<input data-bootstrap-password type="password" autocomplete="new-password" minlength="10"></label><label>Bootstrap secret<input data-bootstrap-secret type="password" autocomplete="off"></label><button type="button" data-bootstrap-submit>Create first Owner</button><div class="command-bootstrap-status" data-bootstrap-status></div></div>`;const form=card.querySelector('.command-auth-form');form?.insertAdjacentElement('afterend',box);box.querySelector('[data-bootstrap-submit]').onclick=submit}
  async function submit(){const root=document.querySelector('[data-bootstrap-owner]');const email=root?.querySelector('[data-bootstrap-email]')?.value.trim();const password=root?.querySelector('[data-bootstrap-password]')?.value||'';const secret=root?.querySelector('[data-bootstrap-secret]')?.value||'';const btn=root?.querySelector('[data-bootstrap-submit]');const status=root?.querySelector('[data-bootstrap-status]');if(!email||password.length<10||!secret){if(status){status.className='command-bootstrap-status error';status.textContent='Email, password (10+ characters) and bootstrap secret are required.'}return}btn.disabled=true;btn.textContent='Creating Owner…';try{const r=await fetch(API()+'/api/public/bootstrap',{method:'POST',headers:{'Content-Type':'application/json','X-Bootstrap-Secret':secret},body:JSON.stringify({email,password})});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error||'Could not create Owner.');if(status){status.className='command-bootstrap-status success';status.textContent='Owner created. You can sign in above now.'}const gateEmail=document.getElementById('command-gate-email');if(gateEmail)gateEmail.value=email;root.querySelectorAll('input').forEach(i=>i.disabled=true);btn.hidden=true;config.bootstrap_required=false;window.dispatchEvent(new CustomEvent('untoz:owner-bootstrap',{detail:{email:esc(email)}}))}catch(e){if(status){status.className='command-bootstrap-status error';status.textContent=e.message||'Could not create Owner.'}}finally{btn.disabled=false;if(!btn.hidden)btn.textContent='Create first Owner'}}
  function boot(){const obs=new MutationObserver(()=>install());obs.observe(document.documentElement,{childList:true,subtree:true});loadConfig()}
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot();
})();
